import React, { useEffect, useMemo, useRef, useState } from 'react';
import sodium from 'libsodium-wrappers-sumo';
import MessageList from './components/MessageList';
import MessageInput from './components/MessageInput';
import ThemeToggle from './components/ThemeToggle';
import SmartSearch from './components/SmartSearch';
import AnnouncementBanner from './components/AnnouncementBanner';
import { Poll, CreatePollModal } from './components/Poll';
import TaskList from './components/TaskList';
import SharedNotes from './components/SharedNotes';
import FileBrowser from './components/FileBrowser';
import TransferHistory from './components/TransferHistory';
import ClipboardSync from './components/ClipboardSync';
import useSocket from './hooks/useSocket';
import servers from './lib/servers';
import { encryptText, decryptText, encryptBytes, decryptBytes, toBase64, fromBase64 } from './lib/e2ee';

function App() {
    const [messages, setMessages] = useState([]);
    const [currentUsername, setCurrentUsername] = useState(localStorage.getItem('lanSaturn_username') || 'Anonymous');
    const [theme, setTheme] = useState(localStorage.getItem('theme') || 'dark');
    const [searchQuery, setSearchQuery] = useState('');
    const [encryptionPassphrase, setEncryptionPassphrase] = useState(localStorage.getItem('lanSaturn_passphrase') || '');
    const [isEncrypted, setIsEncrypted] = useState(!!localStorage.getItem('lanSaturn_passphrase'));
    const [cryptoReady, setCryptoReady] = useState(false);
    const [isTyping, setIsTyping] = useState(false);
    const [typingUser, setTypingUser] = useState('');
    const [isUploading, setIsUploading] = useState(false);
    const [uploadStatus, setUploadStatus] = useState('');
    const [activeServerId, setActiveServerId] = useState('saturn');
    const [activeChannel, setActiveChannel] = useState('general');
    const [activeView, setActiveView] = useState('server');
    const [activeDmUser, setActiveDmUser] = useState('');
    const [announcements, setAnnouncements] = useState([]);
    const [showBroadcastInput, setShowBroadcastInput] = useState(false);
    const [polls, setPolls] = useState([]);
    const [channelTasks, setChannelTasks] = useState([]);
    const [showPollModal, setShowPollModal] = useState(false);
    const [showTransferHistory, setShowTransferHistory] = useState(false);

    const messagesEndRef = useRef(null);
    const activeChannelRef = useRef(activeChannel);
    const encryptionPassphraseRef = useRef(encryptionPassphrase);
    const typingTimeoutRef = useRef(null);

    const { socketRef, connectionStatus, users } = useSocket(activeChannel, currentUsername);

    const activeServer = useMemo(
        () => servers.find(server => server.id === activeServerId) || servers[0],
        [activeServerId]
    );

    const availableDmUsers = useMemo(
        () => users.filter(user => user !== currentUsername && user !== 'Anonymous'),
        [users, currentUsername]
    );

    const allDmUsers = useMemo(() => {
        const dmUsers = new Set();
        messages.forEach(msg => {
            if (msg.type === 'private' && msg.dmUser && msg.dmUser !== 'Anonymous' && msg.dmUser !== currentUsername) {
                dmUsers.add(msg.dmUser);
            }
        });
        availableDmUsers.forEach(user => dmUsers.add(user));
        return Array.from(dmUsers);
    }, [messages, availableDmUsers, currentUsername]);

    // --- Effects ---

    useEffect(() => {
        encryptionPassphraseRef.current = encryptionPassphrase;
        if (!encryptionPassphrase) {
            setIsEncrypted(false);
            localStorage.removeItem('lanSaturn_passphrase');
        } else {
            localStorage.setItem('lanSaturn_passphrase', encryptionPassphrase);
        }
    }, [encryptionPassphrase]);

    useEffect(() => {
        if (currentUsername) {
            localStorage.setItem('lanSaturn_username', currentUsername);
        }
    }, [currentUsername]);

    useEffect(() => {
        sodium.ready.then(() => {
            setCryptoReady(true);
        });
    }, []);

    // Re-decrypt messages when passphrase changes
    useEffect(() => {
        if (!cryptoReady || !encryptionPassphrase) return;

        setMessages(prev => prev.map(message => {
            if (!message.isEncrypted || !message.encryptedPayload || !message.salt || !message.nonce) {
                return message;
            }
            if (
                message.content &&
                !message.content.startsWith('[Encrypted message') &&
                !message.content.startsWith('[Decryption failed')
            ) {
                return message;
            }
            try {
                return {
                    ...message,
                    content: decryptText(message.encryptedPayload, encryptionPassphrase, message.salt, message.nonce)
                };
            } catch (error) {
                return { ...message, content: '[Decryption failed - wrong passphrase or damaged message]' };
            }
        }));
    }, [cryptoReady, encryptionPassphrase]);

    // Socket event listeners (message-level events)
    useEffect(() => {
        const saved = localStorage.getItem('lanSaturn_messages');
        if (saved) {
            setMessages(JSON.parse(saved));
        }

        // Wait for socket to be ready
        const waitForSocket = setInterval(() => {
            if (socketRef.current) {
                clearInterval(waitForSocket);
                setupSocketListeners(socketRef.current);
            }
        }, 50);

        return () => {
            clearInterval(waitForSocket);
            if (typingTimeoutRef.current) {
                clearTimeout(typingTimeoutRef.current);
            }
        };
    }, []);

    function setupSocketListeners(socket) {
        socket.on('user_joined', (data) => {
            addMessage({
                id: `note_${Date.now()}_${Math.random()}`,
                type: 'notification',
                content: `${data.username} joined the chat`,
                channel: activeChannelRef.current,
                timestamp: new Date().toISOString()
            });
        });

        socket.on('user_left', (data) => {
            addMessage({
                id: `note_${Date.now()}_${Math.random()}`,
                type: 'notification',
                content: `${data.username} left the chat`,
                channel: activeChannelRef.current,
                timestamp: new Date().toISOString()
            });
        });

        socket.on('receive_message', async (data) => {
            let content = data.message;
            const currentPassphrase = encryptionPassphraseRef.current;

            if (data.encrypted && currentPassphrase) {
                try {
                    content = decryptText(data.message, currentPassphrase, data.salt, data.nonce);
                } catch (error) {
                    console.error('Message decryption failed:', error);
                    content = '[Decryption failed - wrong passphrase or damaged message]';
                }
            } else if (data.encrypted) {
                content = '[Encrypted message - enter passphrase to view]';
            }

            addMessage({
                id: `msg_${Date.now()}_${Math.random()}`,
                type: 'message',
                username: data.username,
                content,
                channel: data.channel || 'general',
                timestamp: data.timestamp,
                isOwn: false,
                isEncrypted: data.encrypted || false,
                encryptedPayload: data.encrypted ? data.message : undefined,
                encryptionVersion: data.encryptionVersion,
                salt: data.salt,
                nonce: data.nonce,
                reactions: {}
            });
        });

        socket.on('file_shared', (data) => {
            addMessage({
                id: `file_${Date.now()}_${Math.random()}`,
                type: 'file',
                username: data.username,
                filename: data.filename,
                fileUrl: data.fileUrl,
                originalType: data.originalType,
                originalSize: data.originalSize,
                encryptedFile: data.encryptedFile || false,
                encryptionVersion: data.encryptionVersion,
                salt: data.salt,
                nonce: data.nonce,
                channel: data.channel || 'general',
                timestamp: data.timestamp,
                isOwn: false,
                reactions: {}
            });
        });

        socket.on('private_message', (data) => {
            let content = data.message;
            const currentPassphrase = encryptionPassphraseRef.current;

            if (data.encrypted && currentPassphrase) {
                try {
                    content = decryptText(data.message, currentPassphrase, data.salt, data.nonce);
                } catch (error) {
                    console.error('Private message decryption failed:', error);
                    content = '[Decryption failed - wrong passphrase or damaged message]';
                }
            } else if (data.encrypted) {
                content = '[Encrypted message - enter passphrase to view]';
            }

            addMessage({
                id: `dm_${Date.now()}_${Math.random()}`,
                type: 'private',
                username: data.from,
                content,
                dmUser: data.from,
                timestamp: data.timestamp,
                isOwn: false,
                isPrivate: true,
                isEncrypted: data.encrypted || false,
                encryptedPayload: data.encrypted ? data.message : undefined,
                encryptionVersion: data.encryptionVersion,
                salt: data.salt,
                nonce: data.nonce,
                reactions: {}
            });
        });

        socket.on('user_typing', (data) => {
            setTypingUser(data.username);
            setIsTyping(true);
            if (typingTimeoutRef.current) {
                clearTimeout(typingTimeoutRef.current);
            }
            typingTimeoutRef.current = setTimeout(() => {
                setIsTyping(false);
            }, 3000);
        });

        socket.on('user_stopped_typing', () => {
            setIsTyping(false);
            if (typingTimeoutRef.current) {
                clearTimeout(typingTimeoutRef.current);
            }
        });

        socket.on('reaction_added', (data) => {
            setMessages(prev => prev.map(msg => {
                if (msg.id === data.messageId) {
                    const reactions = { ...(msg.reactions || {}) };
                    const usersList = reactions[data.emoji] || [];
                    if (usersList.includes(data.username)) {
                        reactions[data.emoji] = usersList.filter(u => u !== data.username);
                        if (reactions[data.emoji].length === 0) {
                            delete reactions[data.emoji];
                        }
                    } else {
                        reactions[data.emoji] = [...usersList, data.username];
                    }
                    return { ...msg, reactions };
                }
                return msg;
            }));
        });

        // Announcement events
        socket.on('announcement', (data) => {
            setAnnouncements(prev => [data, ...prev].slice(0, 10));
        });

        socket.on('announcements_list', (data) => {
            setAnnouncements(data.announcements || []);
        });

        // Poll events
        socket.on('poll_created', (poll) => {
            setPolls(prev => [...prev, poll]);
        });

        socket.on('poll_updated', (updated) => {
            setPolls(prev => prev.map(p => p.id === updated.id ? updated : p));
        });

        socket.on('polls_list', (data) => {
            setPolls(data.polls || []);
        });

        // Task events
        socket.on('task_created', (data) => {
            setChannelTasks(prev => [...prev, data.task]);
        });

        socket.on('task_updated', (data) => {
            setChannelTasks(prev => prev.map(t => t.id === data.task.id ? data.task : t));
        });

        socket.on('task_deleted', (data) => {
            setChannelTasks(prev => prev.filter(t => t.id !== data.taskId));
        });

        socket.on('tasks_list', (data) => {
            setChannelTasks(data.tasks || []);
        });

        // Request existing data on connect
        socket.emit('get_announcements');
    }

    // Channel switching
    useEffect(() => {
        activeChannelRef.current = activeChannel;
        if (activeView === 'server' && socketRef.current) {
            socketRef.current.emit('join_channel', {
                channel: activeChannel,
                username: currentUsername
            });
            // Fetch polls and tasks for the new channel
            socketRef.current.emit('get_polls', { channel: activeChannel });
            socketRef.current.emit('get_tasks', { channel: activeChannel });
        }
    }, [activeChannel, activeView, currentUsername]);

    // Auto-scroll
    useEffect(() => {
        setTimeout(() => {
            messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
        }, 100);
    }, [messages, activeChannel, activeDmUser, activeView]);

    // Persist messages
    useEffect(() => {
        const savedMessages = messages.map(({ decryptedUrl, decryptedFilename, ...item }) => {
            if (item.isEncrypted) {
                return { ...item, content: '[Encrypted message - enter passphrase to view]' };
            }
            return item;
        });
        localStorage.setItem('lanSaturn_messages', JSON.stringify(savedMessages));
    }, [messages]);

    // --- Handlers ---

    const addMessage = (message) => {
        setMessages(prev => [...prev, message].slice(-100));
    };

    const sendReaction = (messageId, emoji) => {
        if (!socketRef.current) return;
        socketRef.current.emit('add_reaction', {
            messageId,
            emoji,
            username: currentUsername
        });

        setMessages(prev => prev.map(msg => {
            if (msg.id === messageId) {
                const reactions = { ...(msg.reactions || {}) };
                const usersList = reactions[emoji] || [];
                if (usersList.includes(currentUsername)) {
                    reactions[emoji] = usersList.filter(u => u !== currentUsername);
                    if (reactions[emoji].length === 0) {
                        delete reactions[emoji];
                    }
                } else {
                    reactions[emoji] = [...usersList, currentUsername];
                }
                return { ...msg, reactions };
            }
            return msg;
        }));
    };

    const clearHistory = () => {
        const confirmed = window.confirm('Clear all saved chat history on this device?');
        if (!confirmed) return;

        messages.forEach(message => {
            if (message.decryptedUrl) {
                URL.revokeObjectURL(message.decryptedUrl);
            }
        });

        setMessages([]);
        localStorage.removeItem('lanSaturn_messages');
        setSearchQuery('');
        setUploadStatus('Chat history cleared from this device.');
        setTimeout(() => setUploadStatus(''), 3000);
    };

    const sendMessage = async (message) => {
        const cleanMessage = message.trim();
        if (!cleanMessage || !currentUsername) return;

        if (!encryptionPassphrase) {
            addMessage({
                id: `note_${Date.now()}_${Math.random()}`,
                type: 'notification',
                content: 'Enter the shared E2EE passphrase before sending messages.',
                channel: activeChannel,
                timestamp: new Date().toISOString()
            });
            return;
        }

        const timestamp = new Date().toISOString();

        if (activeView === 'dm' && activeDmUser) {
            let dmMessage = cleanMessage;
            let dmEncryptedData = null;

            if (encryptionPassphrase) {
                if (!cryptoReady) {
                    addMessage({
                        id: `note_${Date.now()}_${Math.random()}`,
                        type: 'notification',
                        content: 'Encryption is still loading. Try again in a moment.',
                        channel: activeChannel,
                        timestamp: new Date().toISOString()
                    });
                    return;
                }

                try {
                    dmEncryptedData = encryptText(cleanMessage, encryptionPassphrase);
                    dmMessage = dmEncryptedData.data;
                    setIsEncrypted(true);
                } catch (error) {
                    console.error('DM encryption failed:', error);
                    addMessage({
                        id: `note_${Date.now()}_${Math.random()}`,
                        type: 'notification',
                        content: 'Encryption failed. Check the shared passphrase and try again.',
                        channel: activeChannel,
                        timestamp: new Date().toISOString()
                    });
                    return;
                }
            }

            socketRef.current.emit('private_message', {
                to: activeDmUser,
                message: dmMessage,
                from: currentUsername,
                timestamp,
                encrypted: !!dmEncryptedData,
                encryptionVersion: dmEncryptedData?.encryptionVersion,
                salt: dmEncryptedData?.salt,
                nonce: dmEncryptedData?.nonce
            });

            addMessage({
                id: `dm_${Date.now()}_${Math.random()}`,
                type: 'private',
                username: currentUsername,
                content: cleanMessage,
                dmUser: activeDmUser,
                timestamp,
                isOwn: true,
                isPrivate: true,
                isEncrypted: !!dmEncryptedData,
                encryptedPayload: dmEncryptedData?.data,
                encryptionVersion: dmEncryptedData?.encryptionVersion,
                salt: dmEncryptedData?.salt,
                nonce: dmEncryptedData?.nonce
            });
            return;
        }

        let finalMessage = cleanMessage;
        let encryptedData = null;

        if (encryptionPassphrase) {
            if (!cryptoReady) {
                addMessage({
                    id: `note_${Date.now()}_${Math.random()}`,
                    type: 'notification',
                    content: 'Encryption is still loading. Try again in a moment.',
                    channel: activeChannel,
                    timestamp: new Date().toISOString()
                });
                return;
            }

            try {
                encryptedData = encryptText(cleanMessage, encryptionPassphrase);
                finalMessage = encryptedData.data;
                setIsEncrypted(true);
            } catch (error) {
                console.error('Encryption failed:', error);
                addMessage({
                    id: `note_${Date.now()}_${Math.random()}`,
                    type: 'notification',
                    content: 'Encryption failed. Check the shared passphrase and try again.',
                    channel: activeChannel,
                    timestamp: new Date().toISOString()
                });
                return;
            }
        }

        socketRef.current.emit('send_message', {
            username: currentUsername,
            message: finalMessage,
            channel: activeChannel,
            timestamp,
            encrypted: !!encryptedData,
            encryptionVersion: encryptedData?.encryptionVersion,
            salt: encryptedData?.salt,
            nonce: encryptedData?.nonce
        });

        addMessage({
            id: `msg_${Date.now()}_${Math.random()}`,
            type: 'message',
            username: currentUsername,
            content: cleanMessage,
            channel: activeChannel,
            timestamp,
            isOwn: true,
            isEncrypted: !!encryptedData,
            encryptedPayload: encryptedData?.data,
            encryptionVersion: encryptedData?.encryptionVersion,
            salt: encryptedData?.salt,
            nonce: encryptedData?.nonce
        });

        socketRef.current.emit('typing_stop', { username: currentUsername });
    };

    const handleFileUpload = async (file) => {
        if (!file) return;

        if (activeView === 'dm') {
            setUploadStatus('File upload is available in server channels.');
            setTimeout(() => setUploadStatus(''), 3000);
            return;
        }

        if (!encryptionPassphrase) {
            setUploadStatus('Enter the shared E2EE passphrase before uploading files.');
            return;
        }

        if (!cryptoReady) {
            setUploadStatus('Encryption is still loading. Try again in a moment.');
            return;
        }

        if (file.size > 50 * 1024 * 1024) {
            setUploadStatus('File is too large. Maximum size is 50 MB.');
            return;
        }

        setIsUploading(true);
        setUploadStatus(`Encrypting ${file.name}...`);

        try {
            const plainBytes = new Uint8Array(await file.arrayBuffer());
            const encryptedFile = encryptBytes(plainBytes, encryptionPassphrase);
            const encryptedBlob = new Blob([encryptedFile.cipherBytes], { type: 'application/octet-stream' });
            const formData = new FormData();
            formData.append('file', encryptedBlob, `${file.name}.lsenc`);
            setUploadStatus(`Uploading encrypted ${file.name}...`);

            const response = await fetch('/upload', {
                method: 'POST',
                body: formData
            });
            const result = await response.json();

            if (response.ok && result.success) {
                const timestamp = new Date().toISOString();

                socketRef.current.emit('file_share', {
                    filename: result.filename,
                    fileUrl: result.fileUrl,
                    originalType: file.type || 'application/octet-stream',
                    originalSize: file.size,
                    encryptedFile: true,
                    encryptionVersion: encryptedFile.encryptionVersion,
                    salt: encryptedFile.salt,
                    nonce: encryptedFile.nonce,
                    username: currentUsername,
                    channel: activeChannel,
                    timestamp
                });

                addMessage({
                    id: `file_${Date.now()}_${Math.random()}`,
                    type: 'file',
                    username: currentUsername,
                    filename: result.filename,
                    fileUrl: result.fileUrl,
                    originalType: file.type || 'application/octet-stream',
                    originalSize: file.size,
                    encryptedFile: true,
                    encryptionVersion: encryptedFile.encryptionVersion,
                    salt: encryptedFile.salt,
                    nonce: encryptedFile.nonce,
                    decryptedUrl: URL.createObjectURL(file),
                    decryptedFilename: file.name,
                    channel: activeChannel,
                    timestamp,
                    isOwn: true
                });

                setUploadStatus(`Encrypted and uploaded ${file.name}`);
                setTimeout(() => setUploadStatus(''), 3000);
            } else {
                setUploadStatus(result.error || 'Upload failed');
            }
        } catch (error) {
            console.error('Error encrypting/uploading file:', error);
            setUploadStatus('Encrypted upload failed. Check the passphrase and try again.');
        } finally {
            setIsUploading(false);
        }
    };

    const decryptFileMessage = async (message) => {
        if (!message.encryptedFile) return;

        if (!encryptionPassphrase) {
            setUploadStatus('Enter the shared E2EE passphrase to decrypt this file.');
            return;
        }

        if (!cryptoReady) {
            setUploadStatus('Encryption is still loading. Try again in a moment.');
            return;
        }

        setUploadStatus(`Decrypting ${message.filename}...`);

        try {
            const response = await fetch(message.fileUrl);
            const encryptedBytesData = new Uint8Array(await response.arrayBuffer());
            const plainBytes = decryptBytes(
                encryptedBytesData,
                encryptionPassphrase,
                message.salt,
                message.nonce
            );
            const blob = new Blob([plainBytes], {
                type: message.originalType || 'application/octet-stream'
            });
            const decryptedUrl = URL.createObjectURL(blob);
            const decryptedFilename = message.filename.replace(/\.lsenc$/i, '');

            setMessages(prev => prev.map(item => (
                item.id === message.id
                    ? { ...item, decryptedUrl, decryptedFilename }
                    : item
            )));
            setUploadStatus(`Decrypted ${decryptedFilename}`);
            setTimeout(() => setUploadStatus(''), 3000);
        } catch (error) {
            console.error('File decryption failed:', error);
            setUploadStatus('File decryption failed. Wrong passphrase or damaged file.');
        }
    };

    const handleTyping = () => {
        socketRef.current?.emit('typing_start', { username: currentUsername });
    };

    const handleTypingStop = () => {
        socketRef.current?.emit('typing_stop', { username: currentUsername });
    };

    const toggleTheme = () => {
        const nextTheme = theme === 'dark' ? 'light' : 'dark';
        setTheme(nextTheme);
        localStorage.setItem('theme', nextTheme);
    };

    const openServer = (serverId) => {
        const server = servers.find(item => item.id === serverId) || servers[0];
        setActiveServerId(server.id);
        setActiveChannel(server.channels[0]);
        setActiveView('server');
        setActiveDmUser('');
    };

    const openDm = (username) => {
        setActiveView('dm');
        setActiveDmUser(username);
    };

    const broadcastAnnouncement = (text) => {
        if (!text.trim() || !socketRef.current) return;
        socketRef.current.emit('broadcast_announcement', {
            text: text.trim(),
            username: currentUsername
        });
        setShowBroadcastInput(false);
    };

    const dismissAnnouncement = (id) => {
        setAnnouncements(prev => prev.filter(a => a.id !== id));
    };

    // Poll handlers
    const createPoll = (question, options) => {
        if (!socketRef.current) return;
        socketRef.current.emit('create_poll', {
            question,
            options,
            channel: activeChannel,
            username: currentUsername,
            timestamp: new Date().toISOString()
        });
        setShowPollModal(false);
    };

    const votePoll = (pollId, optionIndex) => {
        if (!socketRef.current) return;
        socketRef.current.emit('vote_poll', {
            pollId,
            optionIndex,
            username: currentUsername
        });
    };

    const closePoll = (pollId) => {
        if (!socketRef.current) return;
        socketRef.current.emit('close_poll', {
            pollId,
            username: currentUsername
        });
    };

    // Task handlers
    const createTask = (text) => {
        if (!socketRef.current) return;
        socketRef.current.emit('create_task', {
            text,
            channel: activeChannel,
            username: currentUsername
        });
    };

    const toggleTask = (taskId) => {
        if (!socketRef.current) return;
        socketRef.current.emit('toggle_task', {
            taskId,
            channel: activeChannel
        });
    };

    const deleteTask = (taskId) => {
        if (!socketRef.current) return;
        socketRef.current.emit('delete_task', {
            taskId,
            channel: activeChannel
        });
    };

    // --- Derived state ---

    const visibleMessages = messages.filter(message => {
        if (activeView === 'dm') {
            return message.type === 'private' && message.dmUser === activeDmUser;
        }
        if (message.type === 'private') return false;
        return (message.channel || 'general') === activeChannel;
    });

    const composerDisabled = activeView === 'dm' && !activeDmUser;
    const title = activeView === 'dm' ? `@${activeDmUser || 'direct-messages'}` : activeView === 'notes' ? '📝 Shared Notes' : activeView === 'filebrowser' ? '📂 Remote File Browser' : activeView === 'clipboardsync' ? '📋 Clipboard Sync' : `#${activeChannel}`;

    // --- Render ---

    return (
        <div className={`app discord-shell ${theme}`}>
            <aside className="server-rail">
                <button
                    className={`server-bubble home ${activeView === 'server' && activeServerId === 'saturn' ? 'active' : ''}`}
                    onClick={() => openServer('saturn')}
                    title="LAN Saturn"
                >
                    LS
                </button>
                <div className="server-divider" />
                {servers.filter(server => server.id !== 'saturn').map(server => (
                    <button
                        key={server.id}
                        className={`server-bubble ${activeView === 'server' && activeServerId === server.id ? 'active' : ''}`}
                        onClick={() => openServer(server.id)}
                        title={server.name}
                    >
                        {server.initials}
                    </button>
                ))}
                <button
                    className={`server-bubble dm-bubble ${activeView === 'dm' ? 'active' : ''}`}
                    onClick={() => {
                        setActiveView('dm');
                        setActiveDmUser(allDmUsers[0] || '');
                    }}
                    title="Direct Messages"
                >
                    DM
                </button>
            </aside>

            <aside className="sidebar-panel">
                <div className="sidebar-title">
                    <span>{activeView === 'dm' ? 'Direct Messages' : activeServer.name}</span>
                    <ThemeToggle theme={theme} onToggle={toggleTheme} />
                </div>

                <div className={`connection-pill ${connectionStatus === 'connected' ? 'connected' : 'offline'}`}>
                    {connectionStatus === 'connected' ? 'Connected' : connectionStatus}
                </div>

                {activeView === 'server' ? (
                    <>
                        <div className="sidebar-section-label">Text Channels</div>
                        <nav className="channel-list">
                            {activeServer.channels.map(channel => (
                                <button
                                    key={channel}
                                    className={`channel-row ${activeView === 'server' && activeChannel === channel ? 'active' : ''}`}
                                    onClick={() => {
                                        setActiveChannel(channel);
                                        setActiveView('server');
                                    }}
                                >
                                    <span>#</span>
                                    {channel}
                                </button>
                            ))}
                        </nav>

                        <div className="sidebar-section-label">Tools</div>
                        <nav className="channel-list">
                            <button
                                className={`channel-row ${activeView === 'notes' ? 'active' : ''}`}
                                onClick={() => setActiveView('notes')}
                            >
                                <span>📝</span>
                                Shared Notes
                            </button>
                            <button
                                className={`channel-row ${activeView === 'filebrowser' ? 'active' : ''}`}
                                onClick={() => setActiveView('filebrowser')}
                            >
                                <span>📂</span>
                                Remote Browser
                            </button>
                            <button
                                className={`channel-row ${activeView === 'clipboardsync' ? 'active' : ''}`}
                                onClick={() => setActiveView('clipboardsync')}
                            >
                                <span>📋</span>
                                Clipboard Sync
                            </button>
                            <button
                                className="channel-row"
                                onClick={() => setShowTransferHistory(true)}
                            >
                                <span>📊</span>
                                Transfer History
                            </button>
                        </nav>

                        <div className="sidebar-section-label">Broadcast</div>
                        <div className="broadcast-section">
                            {showBroadcastInput ? (
                                <form className="broadcast-form" onSubmit={(e) => {
                                    e.preventDefault();
                                    const input = e.target.elements.broadcastText;
                                    broadcastAnnouncement(input.value);
                                    input.value = '';
                                }}>
                                    <input
                                        name="broadcastText"
                                        className="broadcast-input"
                                        placeholder="Type announcement..."
                                        autoFocus
                                        maxLength={500}
                                    />
                                    <div className="broadcast-actions">
                                        <button type="submit" className="broadcast-send-btn">Send</button>
                                        <button type="button" className="broadcast-cancel-btn" onClick={() => setShowBroadcastInput(false)}>Cancel</button>
                                    </div>
                                </form>
                            ) : (
                                <button
                                    className="broadcast-button"
                                    onClick={() => setShowBroadcastInput(true)}
                                >
                                    📢 Broadcast
                                </button>
                            )}
                        </div>
                    </>
                ) : (
                    <>
                        <div className="sidebar-section-label">Direct Messages</div>
                        <nav className="channel-list">
                            {allDmUsers.length === 0 ? (
                                <div className="empty-state">No direct messages yet</div>
                            ) : (
                                allDmUsers.map(user => {
                                    const isOnline = users.includes(user);
                                    return (
                                        <button
                                            key={user}
                                            className={`dm-row ${activeDmUser === user ? 'active' : ''} ${isOnline ? 'online' : 'offline'}`}
                                            onClick={() => openDm(user)}
                                        >
                                            <span className="mini-avatar">{user.charAt(0).toUpperCase()}</span>
                                            <span className="dm-username">{user}</span>
                                            <span className={`status-dot ${isOnline ? 'online' : 'offline'}`} />
                                        </button>
                                    );
                                })
                            )}
                        </nav>
                    </>
                )}

                <div className="account-card">
                    <div className="mini-avatar self">{currentUsername.charAt(0).toUpperCase()}</div>
                    <div>
                        <div className="account-name">{currentUsername}</div>
                        <div className="account-status">Online on LAN</div>
                    </div>
                </div>
            </aside>

            <main className="chat-main">
                <header className="chat-topbar">
                    <div>
                        <h1>{title}</h1>
                        <p>{activeView === 'dm' ? 'Private conversation' : `${activeServer.name} channel`}</p>
                    </div>
                    {activeView !== 'notes' && activeView !== 'filebrowser' && activeView !== 'clipboardsync' && (
                        <div className="chat-topbar-actions">
                            <SmartSearch
                                messages={messages}
                                searchQuery={searchQuery}
                                onSearchChange={setSearchQuery}
                            />
                            <button
                                type="button"
                                className="clear-history-button"
                                onClick={clearHistory}
                            >
                                Clear History
                            </button>
                        </div>
                    )}
                </header>

                {activeView === 'notes' ? (
                    <SharedNotes
                        socket={socketRef.current}
                        channel={activeChannel}
                        username={currentUsername}
                        onClose={() => setActiveView('server')}
                    />
                ) : activeView === 'filebrowser' ? (
                    <FileBrowser
                        socket={socketRef.current}
                        username={currentUsername}
                    />
                ) : activeView === 'clipboardsync' ? (
                    <ClipboardSync
                        socket={socketRef.current}
                        username={currentUsername}
                    />
                ) : (
                    <>
                        <AnnouncementBanner
                            announcements={announcements}
                            onDismiss={dismissAnnouncement}
                        />

                        <div className="encryption-strip">
                            <input
                                type="password"
                                placeholder="Shared E2EE passphrase required"
                                value={encryptionPassphrase}
                                autoComplete="off"
                                onChange={(event) => setEncryptionPassphrase(event.target.value)}
                            />
                            {encryptionPassphrase && (
                                <span>{cryptoReady ? 'E2EE ready' : 'Loading encryption...'}</span>
                            )}
                            {isEncrypted && <span>Encrypted</span>}
                        </div>

                        <MessageList
                            messages={visibleMessages}
                            searchQuery={searchQuery}
                            messagesEndRef={messagesEndRef}
                            onDecryptFile={decryptFileMessage}
                            onReact={sendReaction}
                            currentUsername={currentUsername}
                        />

                        {activeView === 'server' && polls.length > 0 && (
                            <div className="polls-area">
                                {polls.filter(p => !p.closed).map(poll => (
                                    <Poll
                                        key={poll.id}
                                        poll={poll}
                                        currentUsername={currentUsername}
                                        onVote={votePoll}
                                        onClose={closePoll}
                                    />
                                ))}
                            </div>
                        )}

                        {isTyping && (
                            <div className="typing-indicator">
                                {typingUser} is typing...
                            </div>
                        )}

                        {composerDisabled ? (
                            <div className="empty-compose">Choose an online user to start a DM.</div>
                        ) : (
                            <div className="composer-with-actions">
                                <MessageInput
                                    currentUsername={currentUsername}
                                    onUsernameChange={setCurrentUsername}
                                    onSendMessage={sendMessage}
                                    onTyping={handleTyping}
                                    onTypingStop={handleTypingStop}
                                    onFileUpload={handleFileUpload}
                                    isUploading={isUploading}
                                    uploadStatus={uploadStatus}
                                />
                                {activeView === 'server' && (
                                    <button
                                        className="poll-create-trigger"
                                        onClick={() => setShowPollModal(true)}
                                        title="Create Poll"
                                    >
                                        📊
                                    </button>
                                )}
                            </div>
                        )}
                    </>
                )}
            </main>

            {showPollModal && (
                <CreatePollModal
                    onSubmit={createPoll}
                    onCancel={() => setShowPollModal(false)}
                />
            )}

            {showTransferHistory && (
                <TransferHistory
                    onClose={() => setShowTransferHistory(false)}
                />
            )}

            <aside className="members-panel">
                <div className="members-title">Online - {users.length}</div>
                <div className="members-list">
                    {users.length === 0 ? (
                        <div className="empty-state">No users online</div>
                    ) : (
                        users.map((user, index) => (
                            <button
                                key={`${user}_${index}`}
                                className="member-row"
                                onClick={() => user !== currentUsername && openDm(user)}
                            >
                                <span className="mini-avatar">{user.charAt(0).toUpperCase()}</span>
                                <span>{user}</span>
                                {user === currentUsername && <small>You</small>}
                            </button>
                        ))
                    )}
                </div>

                {activeView === 'server' && (
                    <TaskList
                        tasks={channelTasks}
                        onToggle={toggleTask}
                        onDelete={deleteTask}
                        onCreate={createTask}
                    />
                )}
            </aside>
        </div>
    );
}

export default App;
