    right: 0;
    top: calc(100% + 8px);
    width: 380px;
    z-index: 100;
    display: flex;
    flex-direction: column;
}

.search-scope-pills {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    padding: 10px 12px 0;
}

