    letter-spacing: 0.04em;
    padding: 10px 14px 6px;
    text-transform: uppercase;
}

.search-empty {
    color: #949ba4;
    font-size: 13px;
    padding: 18px 14px;
    text-align: center;
}

.search-results-list {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    padding: 0 6px 8px;
}

.search-result-card {
    border-radius: 8px;
    cursor: pointer;
    padding: 8px 10px;
    transition: background-color 0.1s ease;
}

.search-result-card:hover,
.search-result-card.selected {
