    flex-shrink: 0;
    font-size: 16px;
}

.announcement-user {
    color: #a8b3f0;
    font-size: 13px;
    font-weight: 800;
    flex-shrink: 0;
}

.announcement-text {
    color: #dbdee1;
    font-size: 13px;
    line-height: 1.4;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.announcement-dismiss {
    background: transparent;
    color: #949ba4;
    cursor: pointer;
    font-size: 14px;
    flex-shrink: 0;
    padding: 4px;
    border-radius: 4px;
    transition: background-color 0.15s ease, color 0.15s ease;
}

.announcement-dismiss:hover {
    background: rgba(242, 63, 67, 0.2);
    color: #f23f43;
}

.app.light .announcement-banner {
    background: linear-gradient(135deg, rgba(88, 101, 242, 0.1), rgba(235, 69, 158, 0.06));
    border-color: rgba(88, 101, 242, 0.18);
}

.app.light .announcement-text {
    color: #2e3338;
}

/* ======== Broadcast Section ======== */

.broadcast-section {
    padding: 4px 8px 8px;
}

.broadcast-button {
    align-items: center;
    background: rgba(88, 101, 242, 0.12);
    border-radius: 6px;
    color: #a8b3f0;
    cursor: pointer;
    display: flex;
    font-size: 13px;
    font-weight: 700;
    gap: 6px;
    min-height: 36px;
    padding: 0 10px;
    transition: background-color 0.15s ease, color 0.15s ease;
    width: 100%;
}

.broadcast-button:hover {
    background: rgba(88, 101, 242, 0.22);
    color: #c5cbf7;
}

.broadcast-form {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.broadcast-input {
    background: #1e1f22;
    border: 1px solid #5865f2;
    border-radius: 6px;
    color: #dbdee1;
    font-size: 13px;
    height: 34px;
    outline: none;
    padding: 0 10px;
    width: 100%;
}

.broadcast-actions {
    display: flex;
    gap: 6px;
}

.broadcast-send-btn {
    background: #5865f2;
    border-radius: 6px;
    color: #fff;
    cursor: pointer;
    flex: 1;
    font-size: 12px;
    font-weight: 800;
    height: 28px;
}

.broadcast-send-btn:hover {
    background: #4752c4;
}

.broadcast-cancel-btn {
    background: #383a40;
    border-radius: 6px;
    color: #949ba4;
    cursor: pointer;
    flex: 1;
    font-size: 12px;
    font-weight: 800;
    height: 28px;
}

.broadcast-cancel-btn:hover {
    background: #4e5058;
    color: #f2f3f5;
}

.app.light .broadcast-input {
    background: #fff;
    border-color: #5865f2;
    color: #2e3338;
}

.app.light .broadcast-button {
    background: rgba(88, 101, 242, 0.08);
    color: #5865f2;
}

.app.light .broadcast-button:hover {
    background: rgba(88, 101, 242, 0.15);
}

/* ======== Polls ======== */

.polls-area {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 0 18px 10px;
}

.poll-card {
    background: #2b2d31;
    border: 1px solid #3f424a;
    border-radius: 10px;
    overflow: hidden;
    padding: 14px;
}

.poll-card.closed {
    opacity: 0.65;
}

.poll-header {
    align-items: center;
    display: flex;
    gap: 8px;
    margin-bottom: 12px;
}

.poll-icon {
    font-size: 18px;
}

.poll-question {
    color: #f2f3f5;
    font-size: 15px;
    font-weight: 800;
    flex: 1;
}

.poll-closed-badge {
    background: rgba(242, 63, 67, 0.2);
    border-radius: 999px;
    color: #f23f43;
    font-size: 11px;
    font-weight: 800;
    padding: 2px 8px;
}

.poll-options {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.poll-option {
    background: #383a40;
    border: 1px solid transparent;
    border-radius: 8px;
    color: #dbdee1;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 10px;
    min-height: 38px;
    padding: 6px 12px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.15s ease;
    text-align: left;
}

.poll-option:hover:not(.disabled) {
    border-color: #5865f2;
}

.poll-option.selected {
    border-color: #5865f2;
}

.poll-option.disabled {
    cursor: default;
}

.poll-option-bar {
    background: rgba(88, 101, 242, 0.2);
    border-radius: 8px;
    height: 100%;
    left: 0;
    position: absolute;
    top: 0;
    transition: width 0.4s ease;
}

.poll-option.selected .poll-option-bar {
    background: rgba(88, 101, 242, 0.35);
}

.poll-option-text {
    flex: 1;
    font-size: 13px;
    position: relative;
    z-index: 1;
}

.poll-check {
    margin-right: 4px;
}

.poll-option-pct {
    color: #949ba4;
    font-size: 12px;
    font-weight: 800;
    position: relative;
    z-index: 1;
}

.poll-footer {
    align-items: center;
    display: flex;
    gap: 10px;
    margin-top: 10px;
}

.poll-vote-count {
    color: #949ba4;
    font-size: 12px;
}

.poll-creator {
    color: #949ba4;
    font-size: 12px;
}

.poll-close-btn {
    background: rgba(242, 63, 67, 0.15);
    border-radius: 6px;
    color: #f23f43;
    cursor: pointer;
    font-size: 11px;
    font-weight: 800;
    margin-left: auto;
    padding: 4px 10px;
}

.poll-close-btn:hover {
    background: rgba(242, 63, 67, 0.3);
}

.poll-create-trigger {
    background: transparent;
    border: 0;
    cursor: pointer;
    font-size: 20px;
    padding: 8px;
    position: absolute;
    right: 18px;
    bottom: 60px;
    opacity: 0.6;
    transition: opacity 0.15s ease, transform 0.15s ease;
}

.poll-create-trigger:hover {
    opacity: 1;
    transform: scale(1.15);
}

.composer-with-actions {
    position: relative;
}

/* ======== Modal ======== */

.modal-overlay {
    align-items: center;
    background: rgba(0, 0, 0, 0.7);
    display: flex;
    height: 100%;
    justify-content: center;
    left: 0;
    position: fixed;
    top: 0;
    width: 100%;
    z-index: 200;
    animation: fadeIn 0.2s ease;
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

.modal-content {
    background: #2b2d31;
    border: 1px solid #3f424a;
    border-radius: 12px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
    max-width: 440px;
    padding: 24px;
    width: 90%;
    animation: slideUp 0.25s ease;
}

@keyframes slideUp {
    from { opacity: 0; transform: translateY(20px); }
    to { opacity: 1; transform: translateY(0); }
}

.modal-title {
    color: #f2f3f5;
    font-size: 18px;
    font-weight: 800;
    margin: 0 0 16px;
}

.poll-question-input {
    background: #1e1f22;
    border: 1px solid #3f424a;
    border-radius: 8px;
    color: #dbdee1;
    font-size: 14px;
    height: 42px;
    outline: none;
    padding: 0 12px;
    width: 100%;
    margin-bottom: 14px;
}

.poll-question-input:focus {
    border-color: #5865f2;
}

.poll-options-edit {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-bottom: 10px;
}

.poll-option-edit-row {
    display: flex;
    gap: 8px;
}

.poll-option-input {
    background: #1e1f22;
    border: 1px solid #3f424a;
    border-radius: 6px;
    color: #dbdee1;
    flex: 1;
    font-size: 13px;
    height: 36px;
    outline: none;
    padding: 0 10px;
}

.poll-option-input:focus {
    border-color: #5865f2;
}

.poll-remove-option {
    background: rgba(242, 63, 67, 0.15);
    border-radius: 6px;
    color: #f23f43;
    cursor: pointer;
    font-size: 14px;
    height: 36px;
    width: 36px;
}

.poll-remove-option:hover {
    background: rgba(242, 63, 67, 0.3);
}

.poll-add-option {
    background: rgba(88, 101, 242, 0.12);
    border-radius: 6px;
    color: #a8b3f0;
    cursor: pointer;
    font-size: 13px;
    font-weight: 700;
    height: 34px;
    margin-bottom: 16px;
    width: 100%;
}

.poll-add-option:hover {
    background: rgba(88, 101, 242, 0.22);
}

.modal-actions {
    display: flex;
    gap: 10px;
    justify-content: flex-end;
}

.modal-cancel {
    background: #383a40;
    border-radius: 8px;
    color: #dbdee1;
    cursor: pointer;
    font-weight: 800;
    height: 40px;
    padding: 0 18px;
}

.modal-cancel:hover {
    background: #4e5058;
}

.modal-submit {
    background: #5865f2;
    border-radius: 8px;
    color: #fff;
    cursor: pointer;
    font-weight: 800;
    height: 40px;
    padding: 0 18px;
}

.modal-submit:hover {
    background: #4752c4;
}

.modal-submit:disabled {
    cursor: not-allowed;
    opacity: 0.5;
}

/* Light theme modal/poll */
.app.light .poll-card {
    background: #f2f3f5;
    border-color: #d6d9df;
}

.app.light .poll-option {
    background: #ebedef;
    color: #2e3338;
}

.app.light .modal-content {
    background: #fff;
    border-color: #d6d9df;
}

.app.light .poll-question-input,
.app.light .poll-option-input {
    background: #f2f3f5;
    border-color: #d6d9df;
    color: #2e3338;
}

/* ======== Tasks ======== */

.task-list-container {
    border-top: 1px solid #1f2023;
    margin-top: auto;
}

.task-list-header {
    align-items: center;
    background: transparent;
    color: #949ba4;
    cursor: pointer;
    display: flex;
    font-size: 12px;
    font-weight: 800;
    gap: 6px;
    letter-spacing: 0.04em;
    padding: 12px 14px 8px;
    text-transform: uppercase;
    width: 100%;
    text-align: left;
}

.task-list-header:hover {
    color: #f2f3f5;
}

.task-list-icon {
    font-size: 14px;
}

.task-list-title {
    flex: 1;
}

.task-list-count {
    color: #5865f2;
}

.task-list-chevron {
    transition: transform 0.2s ease;
}

.task-list-chevron.open {
    transform: rotate(90deg);
}

.task-list-body {
    padding: 0 8px 8px;
}

.task-empty {
    color: #949ba4;
    font-size: 12px;
    padding: 4px 6px 8px;
}

.task-items {
    display: flex;
    flex-direction: column;
    gap: 2px;
    margin-bottom: 6px;
    max-height: 200px;
    overflow-y: auto;
}

.task-item {
    align-items: center;
    border-radius: 6px;
    display: flex;
    gap: 6px;
    min-height: 30px;
    padding: 2px 6px;
    transition: background-color 0.1s ease;
}

.task-item:hover {
    background: #3a3c43;
}

.task-item.done .task-text {
    color: #949ba4;
    text-decoration: line-through;
}

.task-checkbox {
    background: transparent;
    color: #5865f2;
    cursor: pointer;
    font-size: 16px;
    padding: 0;
    flex-shrink: 0;
}

.task-text {
    color: #dbdee1;
    flex: 1;
    font-size: 13px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.task-delete {
    background: transparent;
    color: #949ba4;
    cursor: pointer;
    font-size: 12px;
    opacity: 0;
    padding: 2px 4px;
    border-radius: 4px;
    transition: opacity 0.15s ease, color 0.15s ease;
}

.task-item:hover .task-delete {
    opacity: 1;
}

.task-delete:hover {
    color: #f23f43;
}

.task-add-form {
    display: flex;
    gap: 4px;
}

.task-add-input {
    background: #1e1f22;
    border: 1px solid #25262b;
    border-radius: 6px;
    color: #dbdee1;
    flex: 1;
    font-size: 12px;
    height: 30px;
    outline: none;
    padding: 0 8px;
}

.task-add-input:focus {
    border-color: #5865f2;
}

.task-add-btn {
    background: #5865f2;
    border-radius: 6px;
    color: #fff;
    cursor: pointer;
    font-size: 16px;
    font-weight: 800;
    height: 30px;
    width: 30px;
}

.task-add-btn:hover {
    background: #4752c4;
}

.task-add-btn:disabled {
    cursor: not-allowed;
    opacity: 0.5;
}

/* Light theme tasks */
.app.light .task-list-container {
    border-color: #d6d9df;
}

.app.light .task-item:hover {
    background: #ebedef;
}

.app.light .task-text {
    color: #2e3338;
}

.app.light .task-add-input {
    background: #fff;
    border-color: #d6d9df;
    color: #2e3338;
}

/* ======== Shared Notes ======== */

.shared-notes-container {
    display: flex;
    flex: 1;
    height: 100%;
    min-height: 0;
    background: #313338;
}

.notes-sidebar {
    width: 220px;
    background: #2b2d31;
    border-right: 1px solid #1f2023;
    display: flex;
    flex-direction: column;
    flex-shrink: 0;
}

.notes-sidebar-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 14px;
    font-size: 13px;
    font-weight: 800;
    color: #949ba4;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    border-bottom: 1px solid #1f2023;
}

.add-note-btn {
    background: transparent;
    color: #dbdee1;
    cursor: pointer;
    font-size: 16px;
    padding: 2px 6px;
    border-radius: 4px;
}

.add-note-btn:hover {
    background: #3a3c43;
    color: #fff;
}

.create-note-form {
    display: flex;
    padding: 10px;
    gap: 6px;
    border-bottom: 1px solid #1f2023;
}

.create-note-form input {
    flex: 1;
    background: #1e1f22;
    border: 1px solid #3f424a;
    border-radius: 4px;
    color: #dbdee1;
    padding: 4px 8px;
    font-size: 12px;
    outline: none;
}

.create-note-form input:focus {
    border-color: #5865f2;
}

.create-note-form button {
    background: #5865f2;
    color: #fff;
    border-radius: 4px;
    font-size: 12px;
    font-weight: 800;
    padding: 4px 8px;
    cursor: pointer;
}

.create-note-form button:hover {
    background: #4752c4;
}

.notes-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.note-item-wrapper {
    display: flex;
    align-items: center;
    border-radius: 4px;
    transition: background-color 0.1s ease;
}

.note-item-wrapper:hover,
.note-item-wrapper.active {
    background: #35373c;
}

.note-item {
    flex: 1;
    background: transparent;
    color: #949ba4;
    text-align: left;
    padding: 8px;
    font-size: 13px;
    font-weight: 600;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    cursor: pointer;
}

.note-item-wrapper.active .note-item,
.note-item-wrapper:hover .note-item {
    color: #f2f3f5;
}

.delete-note-btn {
    background: transparent;
    color: #949ba4;
    padding: 8px;
    cursor: pointer;
    font-size: 12px;
    opacity: 0;
    border-radius: 4px;
}

.note-item-wrapper:hover .delete-note-btn {
    opacity: 1;
}

.delete-note-btn:hover {
    color: #f23f43;
    background: rgba(242, 63, 67, 0.1);
}

.notes-editor-panel {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background: #313338;
}

.editor-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 14px 20px;
    border-bottom: 1px solid #1f2023;
}

.editor-header h2 {
    color: #f2f3f5;
    font-size: 16px;
    margin: 0;
    font-weight: 800;
}

.editor-actions {
    display: flex;
    align-items: center;
    gap: 12px;
}

.toggle-mode-btn {
    background: #383a40;
    color: #dbdee1;
    font-size: 12px;
    font-weight: 800;
    height: 28px;
    padding: 0 12px;
    border-radius: 4px;
    cursor: pointer;
    transition: background-color 0.15s ease;
}

.toggle-mode-btn:hover {
    background: #4e5058;
    color: #fff;
}

.toggle-mode-btn.active {
    background: #5865f2;
    color: #fff;
}

.updater-info {
    color: #23a559;
    font-size: 12px;
    font-weight: 700;
}

.note-textarea {
    flex: 1;
    background: transparent;
    border: 0;
    color: #dbdee1;
    font-family: 'Consolas', 'Courier New', Courier, monospace;
    font-size: 14px;
    line-height: 1.6;
    padding: 20px;
    resize: none;
    outline: none;
    width: 100%;
    height: 100%;
}

.note-preview {
    flex: 1;
    padding: 20px;
    overflow-y: auto;
    color: #dbdee1;
    line-height: 1.6;
    font-size: 15px;
}

.note-preview h1 {
    color: #fff;
    font-size: 1.8em;
    border-bottom: 1px solid #3f424a;
    padding-bottom: 8px;
    margin-bottom: 16px;
}

.note-preview h2 {
    color: #fff;
    font-size: 1.4em;
    margin-top: 24px;
    margin-bottom: 12px;
}

.note-preview h3 {
    color: #fff;
    font-size: 1.2em;
    margin-top: 20px;
    margin-bottom: 8px;
}

.note-preview p {
    margin-bottom: 14px;
}

.note-preview li {
    margin-left: 20px;
    margin-bottom: 6px;
}

.preview-empty, .editor-empty {
    color: #949ba4;
    text-align: center;
    font-style: italic;
    margin-top: 40px;
}

.editor-empty {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    height: 100%;
    margin-top: 0;
}

/* Light theme Notes */
.app.light .shared-notes-container {
    background: #fff;
}

.app.light .notes-sidebar {
    background: #f2f3f5;
    border-color: #e3e5e8;
}

.app.light .notes-sidebar-header,
.app.light .create-note-form,
.app.light .editor-header {
    border-color: #e3e5e8;
