/* ======== Zip Preview ======== */

.zip-preview-container {
    background: #2b2d31;
    border: 1px solid #3f424a;
    border-radius: 6px;
    margin: 8px 0;
    padding: 8px 12px;
    max-width: 400px;
}

.zip-preview-toggle-btn {
    background: transparent;
    color: #7dd3fc;
    cursor: pointer;
    font-size: 13px;
    font-weight: 700;
    padding: 0;
    text-align: left;
}

.zip-preview-toggle-btn:hover {
    text-decoration: underline;
}

.zip-contents-list {
    margin-top: 8px;
    padding-top: 8px;
    border-top: 1px solid #3f424a;
    display: flex;
    flex-direction: column;
    gap: 4px;
    max-height: 150px;
    overflow-y: auto;
}

.zip-file-item {
    display: flex;
    justify-content: space-between;
    font-family: monospace;
    font-size: 11px;
    color: #dbdee1;
