.file-download-row {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-top: 6px;
}

.file-size-info {
    color: #949ba4;
    font-size: 12px;
}

/* ======== Transfer History ======== */

.transfer-history-panel {
    align-items: center;
    background: rgba(0, 0, 0, 0.75);
    display: flex;
    height: 100%;
    justify-content: center;
    left: 0;
    position: fixed;
    top: 0;
    width: 100%;
    z-index: 200;
    animation: fadeIn 0.2s ease;
}

.transfer-history-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 16px;
}

.transfer-history-header h2 {
    color: #f2f3f5;
    font-size: 18px;
    margin: 0;
}

.transfer-header-actions {
    display: flex;
    gap: 10px;
}

.refresh-btn, .close-panel-btn {
    background: #383a40;
    color: #dbdee1;
    font-size: 14px;
    width: 32px;
    height: 32px;
    border-radius: 6px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
}

.refresh-btn:hover, .close-panel-btn:hover {
    background: #4e5058;
    color: #fff;
}

.transfer-search-container {
    margin-bottom: 16px;
}

.transfer-search-input {
    background: #1e1f22;
    border: 1px solid #3f424a;
    border-radius: 6px;
    color: #dbdee1;
    font-size: 13px;
    height: 36px;
    outline: none;
    padding: 0 12px;
    width: 100%;
}

.transfer-search-input:focus {
    border-color: #5865f2;
}

.transfer-table-container {
    background: #2b2d31;
    border: 1px solid #3f424a;
    border-radius: 8px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
    max-width: 800px;
    padding: 24px;
    width: 90%;
    max-height: 80%;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
}

.transfer-loading, .transfer-error, .transfer-empty {
    color: #949ba4;
    text-align: center;
    padding: 30px;
}

.transfer-error {
    color: #f23f43;
}

.transfer-table {
    border-collapse: collapse;
    width: 100%;
    text-align: left;
}

.transfer-table th, .transfer-table td {
    padding: 10px 12px;
    font-size: 13px;
    border-bottom: 1px solid #3f424a;
}

.transfer-table th {
    color: #949ba4;
    font-weight: 800;
    text-transform: uppercase;
    font-size: 11px;
}

.transfer-table td {
    color: #dbdee1;
}

.tx-filename {
    font-weight: 600;
    max-width: 250px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.tx-badge {
    border-radius: 4px;
    font-size: 11px;
    font-weight: 700;
    padding: 2px 8px;
}

.tx-badge.sent {
    background: rgba(35, 165, 89, 0.15);
    color: #23a559;
}

.tx-badge.received {
    background: rgba(88, 101, 242, 0.15);
    color: #5865f2;
}

.tx-hash {
    font-family: monospace;
    font-size: 11px;
    color: #949ba4;
    max-width: 150px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    cursor: help;
}

/* Light theme transfer history */
.app.light .transfer-table-container {
    background: #fff;
    border-color: #d6d9df;
}

.app.light .transfer-table th, .app.light .transfer-table td {
    border-color: #e3e5e8;
}

.app.light .transfer-table td {
    color: #2e3338;
}

.app.light .transfer-search-input {
    background: #f2f3f5;
    border-color: #d6d9df;
    color: #2e3338;
}

/* ======== File Browser ======== */

.file-browser-container {
    display: flex;
    flex-direction: column;
    flex: 1;
    height: 100%;
    min-height: 0;
    background: #313338;
}

.local-share-config {
    padding: 16px 20px;
    background: #2b2d31;
    border-bottom: 1px solid #1f2023;
}

.local-share-config h3 {
    font-size: 14px;
    color: #dbdee1;
    margin: 0 0 10px;
}

.local-share-form {
    display: flex;
    gap: 12px;
    align-items: center;
}

.share-path-input {
    flex: 1;
    background: #1e1f22;
    border: 1px solid #3f424a;
    border-radius: 6px;
    color: #dbdee1;
    height: 38px;
    outline: none;
    padding: 0 12px;
    font-size: 13px;
}

.share-path-input:focus {
    border-color: #5865f2;
}

.save-share-btn {
    background: #5865f2;
    color: #fff;
    border-radius: 6px;
    font-weight: 800;
    height: 38px;
    padding: 0 18px;
    cursor: pointer;
}

.save-share-btn:hover {
    background: #4752c4;
}

.share-status-indicator {
    font-size: 12px;
    font-weight: 800;
    display: flex;
    align-items: center;
    gap: 6px;
}

.share-status-indicator.active {
    color: #23a559;
}

.share-message-feedback {
    margin-top: 6px;
    font-size: 12px;
    color: #7dd3fc;
}

.browser-split-view {
    display: flex;
    flex: 1;
    min-height: 0;
}

.shares-list-sidebar {
    width: 240px;
    background: #2b2d31;
    border-right: 1px solid #1f2023;
    display: flex;
    flex-direction: column;
    flex-shrink: 0;
    padding: 14px;
}

.shares-list-sidebar h4 {
    color: #949ba4;
    font-size: 11px;
    font-weight: 800;
    margin: 0 0 12px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.shares-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
    overflow-y: auto;
}

.shares-empty {
    color: #949ba4;
    font-size: 12px;
    line-height: 1.5;
}

.share-list-item {
    background: transparent;
    border-radius: 6px;
    cursor: pointer;
    display: flex;
    gap: 10px;
    padding: 8px 10px;
    text-align: left;
    transition: background-color 0.1s ease;
    align-items: flex-start;
}

.share-list-item:hover,
.share-list-item.active {
    background: #35373c;
}

.share-list-icon {
    font-size: 18px;
    margin-top: 2px;
}

.share-list-meta {
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.share-list-username {
    color: #f2f3f5;
    font-size: 13px;
    font-weight: 800;
}

.share-list-foldername {
    color: #949ba4;
    font-size: 11px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.share-list-ip {
    color: #5865f2;
    font-size: 10px;
    margin-top: 2px;
}

.remote-files-browser {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.browser-breadcrumb {
    display: flex;
    align-items: center;
    padding: 14px 20px;
    border-bottom: 1px solid #1f2023;
    background: #313338;
    overflow-x: auto;
}

.breadcrumb-user {
    color: #949ba4;
    font-size: 13px;
    font-weight: 800;
}

.breadcrumb-separator {
    color: #4e5058;
    margin: 0 8px;
}

.breadcrumb-root, .breadcrumb-part {
    background: transparent;
    color: #5865f2;
    cursor: pointer;
    font-size: 13px;
    font-weight: 800;
    padding: 0;
}

.breadcrumb-root:hover, .breadcrumb-part:hover {
    text-decoration: underline;
}

.breadcrumb-part {
    color: #dbdee1;
}

.files-list-container {
    flex: 1;
    overflow-y: auto;
    padding: 20px;
}

.files-loading, .files-error, .browser-empty-state {
    color: #949ba4;
    text-align: center;
    padding: 40px;
}

.files-error {
    color: #f23f43;
}

.browser-empty-state {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    height: 100%;
}

.browser-empty-icon {
    font-size: 48px;
    color: #4e5058;
    margin-bottom: 16px;
}

.browser-empty-state h3 {
    color: #f2f3f5;
    margin: 0 0 8px;
}

.files-table {
    border-collapse: collapse;
    width: 100%;
    text-align: left;
}

.files-table th, .files-table td {
    padding: 10px 14px;
    font-size: 13px;
    border-bottom: 1px solid #3f424a;
}

.files-table th {
    color: #949ba4;
    font-weight: 800;
    text-transform: uppercase;
    font-size: 11px;
}

.files-table td {
    color: #dbdee1;
}

.file-row {
    transition: background-color 0.1s ease;
}

.file-row.directory {
    cursor: pointer;
}

.file-row:hover {
    background: rgba(255, 255, 255, 0.03);
}

.file-name-cell {
    font-weight: 600;
}

.file-browser-download-btn {
    background: #23a559;
    color: #fff;
    border-radius: 4px;
    font-size: 11px;
    font-weight: 800;
    padding: 4px 10px;
    cursor: pointer;
    text-decoration: none;
    display: inline-block;
}

.file-browser-download-btn:hover {
    background: #1a7f43;
}

/* Light theme file browser */
.app.light .local-share-config {
    background: #f2f3f5;
    border-color: #e3e5e8;
}

.app.light .local-share-config h3 {
    color: #060607;
}

.app.light .share-path-input {
    background: #fff;
    border-color: #d6d9df;
    color: #2e3338;
}

.app.light .shares-list-sidebar {
    background: #f2f3f5;
    border-color: #e3e5e8;
}

.app.light .share-list-item:hover,
.app.light .share-list-item.active {
    background: #e3e5e8;
}

.app.light .share-list-username {
    color: #060607;
}

.app.light .browser-breadcrumb {
    background: #fff;
    border-color: #e3e5e8;
}

.app.light .files-table th, .app.light .files-table td {
    border-color: #e3e5e8;
}

.app.light .files-table td {
    color: #2e3338;
}

.app.light .file-row:hover {
    background: rgba(0, 0, 0, 0.02);
}

/* ======== Clipboard Sync ======== */

.clipboard-sync-container {
    display: flex;
    flex-direction: column;
    flex: 1;
    height: 100%;
    min-height: 0;
    background: #313338;
    padding: 20px;
}

.clipboard-config {
    background: #2b2d31;
    border: 1px solid #1f2023;
    border-radius: 8px;
    padding: 16px 20px;
    margin-bottom: 20px;
    position: relative;
}

.clipboard-config-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 8px;
}

.clipboard-config h3 {
    font-size: 16px;
    color: #f2f3f5;
    margin: 0;
}

.clipboard-description {
    color: #949ba4;
    font-size: 13px;
    line-height: 1.5;
    margin: 0;
}

/* Toggle Switch Style */
.toggle-switch-container {
    display: flex;
    align-items: center;
    gap: 10px;
}

.switch-label {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 24px;
}

.switch-label input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: #4e5058;
    transition: 0.3s;
    border-radius: 24px;
}

.slider:before {
    position: absolute;
    content: "";
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.3s;
    border-radius: 50%;
}

.switch-label input:checked + .slider {
    background-color: #23a559;
}

.switch-label input:checked + .slider:before {
    transform: translateX(24px);
}

.toggle-status {
    font-size: 11px;
    font-weight: 800;
    color: #949ba4;
}

.switch-label input:checked ~ .toggle-status {
    color: #23a559;
}

.clipboard-status-toast {
    position: absolute;
    right: 20px;
    bottom: 12px;
    background: rgba(88, 101, 242, 0.9);
    color: #fff;
    font-size: 11px;
    font-weight: 800;
    padding: 4px 10px;
    border-radius: 4px;
    animation: fadeIn 0.2s ease;
}

.clipboard-history {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-height: 0;
}

.clipboard-history h4 {
    color: #949ba4;
    font-size: 11px;
    font-weight: 800;
    margin: 0 0 12px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.clipboard-list {
    flex: 1;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding-right: 4px;
}

.clipboard-empty {
    color: #949ba4;
    text-align: center;
    font-style: italic;
    padding: 40px;
}

.clipboard-item {
    background: #2b2d31;
    border: 1px solid #3f424a;
    border-radius: 8px;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.clipboard-item-meta {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.clipboard-item-user {
    color: #a8b3f0;
    font-size: 12px;
    font-weight: 800;
}

.clipboard-item-time {
    color: #949ba4;
    font-size: 11px;
}

.clipboard-item-content {
    display: flex;
    gap: 16px;
    align-items: flex-start;
}

.clipboard-text-pre {
    flex: 1;
    background: #1e1f22;
    border: 1px solid #1f2023;
    border-radius: 6px;
    color: #dbdee1;
    font-family: 'Consolas', 'Courier New', Courier, monospace;
    font-size: 13px;
    margin: 0;
    padding: 10px;
    white-space: pre-wrap;
    word-break: break-all;
    max-height: 120px;
    overflow-y: auto;
}

.clipboard-copy-btn {
    background: #5865f2;
    color: #fff;
    border-radius: 6px;
    font-size: 12px;
    font-weight: 800;
    height: 32px;
    padding: 0 14px;
    cursor: pointer;
    flex-shrink: 0;
}

.clipboard-copy-btn:hover {
    background: #4752c4;
}

/* Light theme clipboard */
.app.light .clipboard-sync-container {
    background: #fff;
}

.app.light .clipboard-config,
.app.light .clipboard-item {
    background: #f2f3f5;
    border-color: #e3e5e8;
}

.app.light .clipboard-config h3 {
    color: #060607;
}

.app.light .clipboard-text-pre {
    background: #fff;
    border-color: #d6d9df;
    color: #2e3338;
